head.script:
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description ETN 마스터  목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SISUDATE, edt_EISUDATE) === false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) === false) {
        return false;
    }
    dts_detail.removeAll();
    cmb_cb_p_group.setValue("");
    cmb_cb_p_attr_1.setValue("");
    cmb_cb_p_attr_2.setValue("");
    cmb_cb_p_attr_3.setValue("");
    cmb_cb_p_attr_4.setValue("");
    rdo_BAS_IDX_CNTR_TP.setValue("");
    rdo_BAS_IDX_CLSS.setValue("");

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_detail
 * @description etn 상세 조회한다.
 * @param {String} STD_CD STD_CD
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_detail = async function(STD_CD) {
    dts_detail.removeAll();
    const sbmOptions = {
        id : "sbm_dts_detail",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_detail=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name clickRdoTp
 * @description click Rdo Tp 처리
 * @returns {void}
 * @hidden N
 */
scwin.clickRdoTp = function() {
    let BAS_IDX_CNTR_TP_CD = rdo_BAS_IDX_CNTR_TP.getValue();
    if (BAS_IDX_CNTR_TP_CD !== "99") {
        txb_BAS_IDX_CNTR_TP_MISC.setValue("");
        txb_BAS_IDX_CNTR_TP_MISC.setDisabled(true);
        txb_BAS_IDX_CNTR_TP_MISC.style.backgroundColor = '#b9d4f7';
    } else {
        txb_BAS_IDX_CNTR_TP_MISC.setDisabled(false);
        txb_BAS_IDX_CNTR_TP_MISC.style.backgroundColor = 'white';
    }
};

/**
 * @method
 * @name clickRdoClss
 * @description click Rdo Clss 처리
 * @returns {void}
 * @hidden N
 */
scwin.clickRdoClss = function() {
    let BAS_IDX_CLSS_CD = rdo_BAS_IDX_CLSS.getValue();
    if (BAS_IDX_CLSS_CD !== "99") {
        txb_BAS_IDX_CLSS_MISC.setValue("");
        txb_BAS_IDX_CLSS_MISC.setDisabled(true);
        txb_BAS_IDX_CLSS_MISC.style.backgroundColor = '#b9d4f7';
    } else {
        txb_BAS_IDX_CLSS_MISC.setDisabled(false);
        txb_BAS_IDX_CLSS_MISC.style.backgroundColor = 'white';
    }
};

/**
 * @method
 * @name formCheck
 * @description 폼을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.formCheck = async function() {
    if (txb_ISUR_CD.getValue() === "" || txb_ISUR_CD.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if (txb_ISU_NM.getValue() === "" || txb_ISU_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
        txb_ISU_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_NM, 80, "한글종목명")) {
        txb_ISU_NM.focus();
        return false;
    }
    if (txb_ISU_ABBRV.getValue() === "" || txb_ISU_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 40, "한글종목약명")) {
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ENG_NM.getValue() === "" || txb_ISU_ENG_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV.getValue() === "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (rdo_BAS_IDX_CNTR_TP.getValue() === "99" && (txb_BAS_IDX_CNTR_TP_MISC.getValue().indexOf(" ") === "" || txb_BAS_IDX_CNTR_TP_MISC.getValue() === "")) {
        await $c.win.alert("기초지수국가구분이 기타일 경우에는 내용을 입력해 주시기 바랍니다.");
        txb_BAS_IDX_CNTR_TP_MISC.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_IDX_CNTR_TP_MISC, 40, "기초지수 국가 구분 기타")) {
        txb_BAS_IDX_CNTR_TP_MISC.focus();
        return false;
    }
    if (rdo_BAS_IDX_CLSS.getValue() === "99" && (txb_BAS_IDX_CLSS_MISC.getValue().indexOf(" ") === "" || txb_BAS_IDX_CLSS_MISC.getValue() === "")) {
        await $c.win.alert("기초지수분류가 기타일 경우에는 내용을 입력해 주시기 바랍니다.");
        txb_BAS_IDX_CLSS_MISC.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_IDX_CLSS_MISC, 40, "기초지수분류 기타")) {
        txb_BAS_IDX_CLSS_MISC.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
        txa_NUSUAL_ISU_COND_CONTN.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_MEMO_CONTN, 200, "담당자메모")) {
        txa_MEMO_CONTN.focus();
        return false;
    }

    // CFI체크
    if (cmb_cb_p_group.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
        cmb_cb_p_group.focus();
        return false;
    }
    if (cmb_cb_p_attr_1.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
        cmb_cb_p_attr_1.focus();
        return false;
    }
    if (cmb_cb_p_attr_2.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
        cmb_cb_p_attr_2.focus();
        return false;
    }
    if (cmb_cb_p_attr_3.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
        cmb_cb_p_attr_3.focus();
        return false;
    }
    if (cmb_cb_p_attr_4.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
        cmb_cb_p_attr_4.focus();
        return false;
    }
};

/**
 * @method
 * @name changeCfi
 * @description cfi 변경 설정 - 채권과 동일 .....
 * @returns {void}
 * @hidden N
 */
scwin.changeCfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    let cfi = "";
    cfi = "D";
    if (cmb_cb_p_group.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_group.getValue();
    if (cmb_cb_p_attr_1.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_1.getValue();
    if (cmb_cb_p_attr_2.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_2.getValue();
    if (cmb_cb_p_attr_3.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_3.getValue();
    if (cmb_cb_p_attr_4.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_4.getValue();
    txb_CFI_CD.setValue(cfi); // cfi 설정

};

/**
 * @method
 * @name setChange
 * @description 상세 조회시 CFI 상세 설정
 * @param {String} str_cfi str_cfi
 * @returns {void}
 * @hidden N
 */
scwin.setChange = function(str_cfi) {
    if (str_cfi === "") return;
    cmb_cb_p_group.setValue(str_cfi.substring(1, 2));
    cmb_cb_p_attr_1.setValue(str_cfi.substring(2, 3));
    cmb_cb_p_attr_2.setValue(str_cfi.substring(3, 4));
    cmb_cb_p_attr_3.setValue(str_cfi.substring(4, 5));
    cmb_cb_p_attr_4.setValue(str_cfi.substring(5, 6));
};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달 값을 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
};

/**
 * @method
 * @name ins_modify
 * @description etn 표준코드  수정한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_modify = async function() {
    dts_detail.setCellData(dts_detail.getRowPosition(), "CRUDSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    trs_modify.KeyName = "toinb_dataid4";
    // [전환검토] trs_modify.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_modify",
        action : "/StdCdEtnInfoAction.do",
        ref : "dts_Rst,dts_detail",
        target : "trs_modify=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name ins_remove
 * @description etn 삭제처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_remove = async function() {

    // dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "STD_CD", txb_STD_CD.getValue());
    dts_Delete.setCellData(1, "ISU_NM", txb_ISU_NM.getValue());
    dts_Delete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    trs_remove.KeyName = "toinb_dataid4";
    // [전환검토] trs_remove.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_remove",
        action : "/StdCdEtnInfoAction.do",
        ref : "dts_Delete",
        target : "trs_remove=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name chkHan
 * @description 한글 입력불가
 * @param {*} Obj Obj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkHan = async function(Obj) {
    const limit_char = /[ㄱ-ㅎ|ㅏ-ㅣ|가-힝]/g;
    const numstr = Obj.getValue();
    if (limit_char.test(numstr)) {
        await $c.win.alert("한글은 입력할 수 없습니다.");
        Obj.focus();
    }
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.libRoundPanel.PanelToGroupBox(panel_2);

    // PanelToGroupBox(panel_3);
    // PanelToGroupBox(panel_4);
    // PanelToGroupBox(panel_6);

    ins_combo_set(dts_CURR_TP_CD, "ULDINS16400.xml", SCREN_PROCS_TP_CD_01, "02475", "SEL"); // 통화코드
    ins_combo_set(dts_LIST_STAT_CD, "ULDINS16400.xml", SCREN_PROCS_TP_CD_01, "00714", "SEL"); // 00714 - D:상장폐지I:미발행N:비상장Y:상장Z:기타
    ins_combo_set(dts_STD_CD_APCT_TP_CD, "ULDINS16400.xml", SCREN_PROCS_TP_CD_01, "03527"); // 03527 - 신청자구분
    ins_combo_set(dts_ETP_PROD_TP_CD, "ULDINS16400.xml", SCREN_PROCS_TP_CD_01, "03903", "SEL"); // ETP상품구분코드
    dts_ETP_PROD_TP_CD.removeRow("1");
    dts_ETP_PROD_TP_CD.removeRow("2");

    // cfi콤보셋팅
    ins_cfi_set(dts_cfi_group, "ULDINS16400.xml", SCREN_PROCS_TP_CD_01, "13", "D", "", "", "G");
    fn_CtrlBtn_temp("no_data");
    txb_DEL_RSN.hide();
    txb_STD_CD_APPL_ID.hide();
    txb_param1.hide();
    txb_param2.hide();
    txa_REF_CONTN.hide();

    // hidden패널
    panel_12.hide();

    // 최대수익액, 최대손실액, 발행가액 없앤다 2013.12.5
    edt_BND_ISU_PRC.hide();

    // 2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------
    btn_clearPwd.hide();
    // 2016.09.20 표준코드 ID 생성으로 인한 필요없는 항목 삭제----------------------------------

    const arrObjectApct = [txb_APCT_NM, txb_APCT_FAX_NO, txb_APCT_TEL_NO, txb_APCT_INNR_NO];
    for (let i = 0; i < arrObjectApct.length; i++) {
        fn_apct_delchar(arrObjectApct[i]);
    }
    txb_pSTD_CD.focus();
};

