/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnClick = async function(row, colid) {
    if (row === 0) return;
    const STD_CD = dts_List.getCellData(row, "STD_CD");
    await scwin.ins_detail(STD_CD);
};

/**
 * @method
 * @name btn_file_onclick
 * @description 「첨부파일확인」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_file_onclick = function() {
    /*
    	txb_param1 에는 신청ID
    	txb_param2 에는 구분값을 넣는데..
         + "1 : 발행기관신청, 팩스-발행기관신청 \n"
    	 + "2 : 표준코드신청, 팩스-표준코드신청 \n"
    	 + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
     */
    txb_param1.setValue(txb_STD_CD_APPL_ID.getValue()); // 표준코드  신청 ID
    txb_param2.setValue("2");
    fn_GetPar = scwin.getParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function() {
    if (await scwin.formCheck() === false) return;
    ins_popupOpen(txb_DEL_RSN, "", "ULDINS93900", "수정사유", "470", "190");
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_delete_onclick = function() {
    txb_param1.setValue("");
    txb_param2.setValue("");
    fn_GetPar = scwin.getParam;
    // 삭제 신청건수 확인후
    const DELCNT = dts_detail.getCellData(dts_detail.rowpositon, "DELCNT");
    if (Number(DELCNT) > 0) {
        // 삭제 메시지 확인 ... 확인되면 -> 삭제승인 화면이동 ,null,null, 아니면 바로 삭제
        fn_alertRequiredDelByWeb();
    } else {
        // 관리 삭제로직
        // 삭제팝업호출
        // 삭제사유 전달받을 input박스 정의한다.
        const rtn = fn_alertDelConfirm();
        if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

        {
            ins_popupOpen(txb_DEL_RSN, "", "ULDINS91500", "삭제사유", "470", "170");
        }
        // ins_remove() 함수를 자동호출 하므로 삭제 함수를 만들어 두어야 한다.

    }
};

