/**
 * @method
 * @name dts_detail_OnLoadCompleted
 * @description dts_detail 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_detail_OnLoadCompleted = async function(rowcount) {
    const ACTIV_YN = dts_List.getCellData(dts_List.rowpositon, "ACTIV_YN"); // 발행기관 활성여부
    if (ACTIV_YN === "N") {
        await $c.win.alert("해당회사는 비활성 발행기관입니다.");
    }
    if (rowcount > 0) {
        const str_cfi = dts_detail.getCellData(dts_detail.rowpositon, "CFI_CD");
        scwin.setChange(str_cfi);
        fn_CtrlBtn_temp("update");
        let BAS_IDX_CNTR_TP_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "BAS_IDX_CNTR_TP_CD");
        rdo_BAS_IDX_CNTR_TP.setValue(BAS_IDX_CNTR_TP_CD);
        scwin.clickRdoTp();
        let BAS_IDX_CLSS_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "BAS_IDX_CLSS_CD");
        rdo_BAS_IDX_CLSS.setValue(BAS_IDX_CLSS_CD);
        scwin.clickRdoClss();
        const lst_yn = dts_detail.getCellData(dts_detail.rowpositon, "LIST_STAT_CD");
        // var pre_simsa_pass_yn = dts_detail.NameValue(dts_detail.rowpositon, "PRE_SIMSA_PASS_YN");
        // var pre_simsa_reject_yn = dts_detail.NameValue(dts_detail.rowpositon, "PRE_SIMSA_REJECT_YN");
        // var simsa_yn = dts_detail.NameValue(dts_detail.rowpositon, "SIMSA_YN");

        /*
         * LIST_BZ_TP_CD (701 : 예비심사, 702 : 신규상장)
         * LIST_PROCS_STAT_CD (02:반송, 03:반송과 한세트. 반송으로 간주. 50:삭제)
         * 반송, 삭제만 수정, 삭제 가능.
         */
        const list_bz_tp_cd = dts_detail.getCellData(dts_detail.rowpositon, "LIST_BZ_TP_CD");
        const list_procs_stat_cd = dts_detail.getCellData(dts_detail.rowpositon, "LIST_PROCS_STAT_CD");
        let btnflag = false;
        if (lst_yn === "Y") {
            // alert("상장종목은 수정할 수 없습니다. \n증권상품시장부와 협의하시기 바랍니다.");
            btnflag = true;
        } else if (lst_yn === "N" &&
            (list_procs_stat_cd !== "" && list_procs_stat_cd !== "02" && list_procs_stat_cd !== "03" && list_procs_stat_cd !== "50")) {
            let msg = "";
            if (list_bz_tp_cd === "701") msg = "[예비심사] 중인 종목은";
            if (list_bz_tp_cd === "702") msg = "[신규상장] 심사중인 종목은";
            await $c.win.alert(msg + "수정 및 삭제할 수 없습니다. \n증권상품시장부와 협의하시기 바랍니다.");
            btnflag = true;
        }

        /*if ( simsa_yn == "Y" ) {
        	alert("신규상장 처리중 종목은 수정 및 삭제할 수 없습니다. \n증권상품시장부와 협의하시기 바랍니다");
        	btnflag = true;
        }*/

        if (btnflag === true) {
            btn_modify.setDisabled(true);
            btn_modify.setBackgroundImage("../img/ins/btn_modify_d.gif");
            btn_delete.setDisabled(true);
            btn_delete.setBackgroundImage("../img/ins/btn_delete_d.gif");

            // alert 삭제 및 비밀번호 초기화도 제어 추가 20140116
            btn_clearPwd.setDisabled(true);
            btn_clearPwd.setBackgroundImage("../img/ins/btn_clearPwd_d.gif");
        }
    } else {
        scwin.setChange("");
        fn_CtrlBtn_temp("no_data");
    }
};

